      faqs: [{ question: "ما برنامج تقدير تكاليف الإنشاء؟", answer: "يساعد المهنيين على تنظيم نطاق المشروع والكميات والأسعار والافتراضات والمخرجات. ويظل المقدّر مسؤولاً عن دقة التقدير والحكم التجاري الذي يستند إليه." }, { question: "كيف يُستخدم BOQ في التقدير؟", answer: "يوفر BOQ بنودًا وكميات منظّمة يمكن أن تدعم التسعير. ويراجع المقدّر النطاق ويطبق الأسعار والمخاطر والتكاليف العامة والاستبعادات." }, { question: "ما الفرق بين حصر الكميات والتقدير؟", answer: "يقيس حصر الكميات المقادير من الرسومات أو النماذج. أما التقدير فيطبق الأسعار والمخاطر والافتراضات التجارية على الكميات التي تمت مراجعتها." }, { question: "هل يمكن لـ Quantara حساب الأسعار الكاملة للمشروع؟", answer: "يمكن لـ Quantara حساب الإجماليات المدعومة من المدخلات المهنية، لكنها لا تنشئ أسعارًا تجارية من تلقاء نفسها ولا تضمن السعر النهائي للمشروع." }, { question: "كيف يجب مراجعة الأسعار والافتراضات؟", answer: "يجب على مقدّر أو مدير تجاري مؤهل فحص الأسعار والكميات والافتراضات والاستبعادات والصيغ والإجماليات قبل التقديم." }, { question: "هل يمكن تعديل التقديرات؟", answer: "تحتفظ Quantara بسجلات منفصلة لمراجعات BOQ. ويجب على المستخدمين مقارنة السجلات وتفسير أي تغييرات في النطاق أو الجانب التجاري." }, { question: "هل يمكن إنشاء مخرجات لمراجعة العميل؟", answer: "يمكن إنشاء مخرجات مدعومة بصيغتي PDF وXLSX للمراجعة. ويجب على مهني فحصها قبل تقديمها إلى العميل." }, { question: "هل تحل Quantara محل المدير التجاري؟", answer: "لا. تنظّم Quantara البيانات المدعومة، بينما تظل القرارات الاستراتيجية والتجارية وقرارات إدارة المخاطر من مسؤولية الفريق المهني." }],
