      workflowProblem: { heading: "مشكلة الجداول في ملفات PDF", paragraphs: ["غالبًا ما يصدر الاستشاريون جداول الكميات في مستندات PDF للحد من التعديل العشوائي، لكن الصيغة وحدها لا تضمن سلامة المحتوى ولا تمنع العبث به. وقد يؤدي نسخ جدول من PDF إلى جدول بيانات إلى تغيير العلاقات بين الصفوف أو الأعمدة أو الأوصاف.", "قد تتطلب الجداول المعقدة ذات أوصاف البنود متعددة الأسطر والعناوين المدمجة والتسلسل الهرمي الضمني إعادة بناء يدوية ومراجعة مهنية بعد التقاط النص."] },
      quantaraSupport: { heading: "تحليل ذكي للجداول", paragraphs: ["يخزّن Quantara طبقة النص المتاحة ويطبق تحليل الجداول المدعوم. وقد تتطلب التخطيطات المعقدة والخلايا المدمجة والتسلسل الهرمي الضمني والجداول الممتدة عبر الصفحات تصحيحًا.", "لا تصبح عناصر مرشحة للمراجعة إلا صفوف الجداول المدعومة المكتشفة؛ أما نص الفقرات العادية فيبقى محتوى مصدر مخزنًا. ويجب على مقدّر التكاليف مقارنة كل عنصر مرشح بملف PDF الأصلي قبل اعتماد بيانات BOQ المنظمة."] },
      relevantFeatures: [{ name: "التقاط الجداول المدعومة", description: "تخزين النص المتاح والتقاط هياكل الجداول المدعومة المكتشفة من ملفات PDF النصية." }, { name: "معالجة PDF صفحةً بصفحة", description: "معالجة المحتوى المدعوم عبر صفحات PDF؛ مع بقاء استمرارية الجداول وتسلسلها الهرمي خاضعين للمراجعة." }, { name: "مراجعة المصدر", description: "فتح سجلات المصدر والنتائج الملتقطة لإجراء المقارنة والتصحيح المهنيين." }],
