      faqs: [{ question: "هل يستطيع Quantara استخراج جداول BOQ من PDF؟", answer: "يخزّن Quantara نص PDF المتاح وينشئ عناصر مرشحة للمراجعة من صفوف الجداول المدعومة المكتشفة. لا يتحول نص الفقرات العادية إلى عناصر BOQ مرشحة، وتتطلب كل نتيجة جدول مراجعة." }, { question: "ما ملف PDF النصي؟", answer: "يُنشأ ملف PDF النصي رقميًا، مثلًا بتصديره من Word أو Excel، ولذلك يمكن عادةً تحديد نصه بالمؤشر." }, { question: "هل يمكن استخراج الجداول المعقدة؟", answer: "يمكن التقاط بعض الجداول المدعومة، لكن التنسيق غير المنتظم والتسلسل الهرمي الضمني والهياكل الممتدة عبر الصفحات قد تتطلب تصحيحًا أو إعادة بناء يدويين." }, { question: "ماذا يحدث للخلايا المدمجة؟", answer: "قد تنتج الخلايا المدمجة بنية ملتبسة وقد تتطلب فصلًا أو إعادة بناء يدويين. ويجب ألا يفترض المستخدمون بقاء المطابقة الأصلية محفوظة." }, { question: "هل يمكن أن تُقرأ الكميات بصورة خاطئة؟", answer: "نعم. قد تؤثر مشكلات التخطيط والتحليل في الأوصاف والوحدات والكميات، ولذلك تكون المراجعة المهنية الدقيقة إلزامية." }, { question: "هل يشمل استخراج PDF الرسومات؟", answer: "لا. يخزّن Quantara نص PDF القابل للاستخراج وينشئ عناصر مرشحة فقط من صفوف الجداول المدعومة المكتشفة، وليس من الأشكال الهندسية أو القياسات الواردة في الرسومات الفنية." }, { question: "هل يمكن تصدير البيانات المستخرجة؟", answer: "نعم، بعد مراجعتها يمكن تصدير البيانات المنظمة إلى XLSX." }, { question: "ما الذي يجب على المستخدمين مراجعته بعد الاستخراج؟", answer: "يجب على المستخدمين مقارنة أوصاف البنود والوحدات والكميات والتسلسل الهرمي والإجماليات بمستند المصدر قبل الاستخدام التجاري." }],
