      summary: "كثيرًا ما يحدث خلط بين جدول الكميات (BOQ) وقائمة المواد (BOM)، لكنهما يخدمان قطاعات ومراحل مختلفة من المشروع. BOQ مستند إنشاءات يوضح العمالة والمواد ومنهجية تنفيذ الأعمال، بينما BOM مستند للتصنيع أو المشتريات يسرد الأجزاء المادية والمواد الخام اللازمة لتجميع منتج فقط.",
      sections: [
        { id: "why-it-matters", heading: "أهمية التمييز بينهما", paragraphs: ["يساعد فهم متى يُستخدم BOQ ومتى تُستخدم BOM فرق MEP ومقاولي التجهيز الداخلي ومديري المشتريات على تمييز فئات تكاليف المواد والعمالة والتركيب والتحقق منها.", "تخبرك BOM بما يجب شراؤه. أما BOQ فيوضح ما يجب شراؤه وكيفية تركيبه وما يتضمنه نشاط الإنشاء عمومًا."] },
        { id: "core-differences", heading: "بنود الأعمال مقابل مكونات المواد", bullets: ["النطاق: يشمل بند BOQ، مثل إنشاء جدار بلوك بسماكة 200mm، البلوك والمونة وعمالة البناء والمعدات. أما BOM فتسرد المواد فقط.", "السياق: تنشأ BOM في مجالي التصنيع والهندسة، بينما تختص ملفات BOQ بالهندسة المدنية والإنشاءات.", "المشتريات: تُسلّم BOM إلى المورد لشراء الأجزاء، بينما يُسلّم BOQ إلى مقاول الباطن لتنفيذ الأعمال."] },
        { id: "comparison-table", heading: "مقارنة جنبًا إلى جنب", table: { headers: ["الخاصية", "جدول الكميات (BOQ)", "قائمة المواد (BOM)"], rows: [["التركيز الأساسي", "أنشطة الإنشاء المكتملة", "المواد الخام والأجزاء المادية"], ["هل يشمل العمالة؟", "نعم، تُسعّر العمالة ضمن السعر", "لا، تكاليف المواد فقط"], ["القطاع", "الإنشاءات والهندسة المدنية وMEP", "التصنيع وتجميع المنتجات وسلسلة التوريد"], ["القياس", "العمل المنجز، مثل الأمتار المربعة من الجدار", "المدخلات الخام، مثل عدد قوالب الطوب"]] } },
        { id: "practical-example", heading: "مثال عملي", paragraphs: ["لنأخذ حزمة افتراضية لتركيب الإضاءة.", "بند BOQ: توريد وتركيب وتشغيل وحدات إضاءة LED مقاس 600x600 في سقف معلّق، الكمية: 50.", "بند BOM للحزمة نفسها: وحدات إضاءة LED ووحدات تشغيل وكابلات وحوامل تثبيت، كل منها بكميته المحددة."] },
        { id: "limitations", heading: "الحدود ومواطن التداخل", paragraphs: ["يستخدم بعض مقاولي الإنشاءات المتخصصين، مثل مصنّعي الهياكل الفولاذية أو البنّائين بالوحدات مسبقة الصنع، المستندين معًا. فهم يستخدمون BOQ للفوز بالعقد مع العميل، ثم ينشئون BOM للمصنع كي ينتج المكونات فعليًا.", "ينطوي التعامل مع BOM باعتبارها BOQ على مخاطر، لأنها تتجاهل التكاليف المهمة للعمالة وإدارة الموقع واستئجار المعدات وتعقيد التركيب."] },
        { id: "quantara-workflow", heading: "كيف تدعم Quantara سير العمل", paragraphs: ["Quantara برنامج لسير عمل BOQ بمساعدة AI. يلتقط معلومات المشروع المدعومة للمراجعة وينظّم بنود الأعمال المؤكدة والمراجعات وسجلات المشروع.", "تدعم Quantara سجلات BOQ والمخرجات المهنية، وليست نظامًا لقوائم مواد التصنيع أو لإدارة المخزون."] }
      ],
      faqs: [{ question: "هل يمكن تحويل BOQ إلى BOM؟", answer: "نعم، لكن ذلك يتطلب من مقدّر أو مهندس تفكيك بنود الأعمال في BOQ إلى المواد الخام المكوّنة لها واستبعاد عناصر العمالة." }, { question: "هل يستخدم مقاولو MEP مستند BOM أم BOQ؟", answer: "يسعّر مقاولو MEP عادةً BOQ للفوز بالمشروع، بينما ينشئ فريق المشتريات لديهم BOM لطلب المواد من الموردين." }, { question: "هل تشمل BOM الهدر؟", answer: "نعم، تتضمن BOM العملية عادةً نسبة هدر للمواد، بينما يعرض BOQ عادةً الكميات الصافية للأعمال المنجزة." }, { question: "هل تتساوى الكميات في BOQ وBOM؟", answer: "نادرًا. فقد يقيس BOQ جدارًا بالأمتار المربعة، بينما تقيس BOM المقابلة الطوب والمونة والروابط كل عنصر على حدة." }, { question: "أي المستندين يُعد مستندًا تعاقديًا؟", answer: "في الإنشاءات، يكون BOQ المسعّر عادةً جزءًا من العقد. أما BOM فهي عادةً مستند مشتريات داخلي." }],
