      summary: "يتناول كل من جدول الكميات (BOQ) وتقدير تكلفة الإنشاء تكاليف المشروع ونطاقه، لكن لكل منهما غرض مختلف. يكون BOQ عادةً مستند مناقصة رسميًا يحدد الكميات التي يسعّرها المقاولون، بينما يمثل التقدير حسابًا داخليًا للتكاليف والمصاريف العامة والهوامش والمخاطر.",
