        { id: "core-differences", heading: "الهيكل والغرض", paragraphs: ["تكمن الفروق الأساسية في الجمهور المستهدف ومستوى التفصيل:"], bullets: ["الجمهور: BOQ مستند خارجي مشترك بين العميل والمقاول، بينما التقدير مستند داخلي سري.", "الأسعار: يتضمن BOQ سعر بيع واحدًا لكل بند، بينما يفصّل التقدير هذا السعر إلى تكاليف العمالة والمعدات والمواد ومقاولي الباطن.", "المخاطر: يعرض BOQ الكميات الصافية، بينما يشمل التقدير نسب الهدر والاحتياطيات وتوزيع المصاريف العامة."] },
        { id: "comparison-table", heading: "نظرة عامة على المقارنة", table: { headers: ["الخاصية", "جدول الكميات (BOQ)", "تقدير تكلفة الإنشاء"], rows: [["المستخدم الأساسي", "العميل ومسّاح الكميات والمقاول المتقدم بالعطاء", "فريق التقدير الداخلي والمدير التجاري"], ["الغرض", "توحيد المناقصة والتقييم", "حساب التكاليف الفعلية وتحديد سعر العرض"], ["إمكانية الاطلاع", "مشترك بين أطراف التعاقد", "سري تمامًا وداخلي"], ["هيكل السعر", "سعر وحدة موحّد واحد، سعر البيع", "تفصيل دقيق: التكلفة + الهامش + المصاريف العامة"]] } },
        { id: "practical-example", heading: "مثال عملي", paragraphs: ["في حزمة HVAC افتراضية، قد يذكر BOQ بند توريد وتركيب مجاري هواء بطول 100 متر طولي.", "يأخذ المقدّر بند BOQ ويبني تقديرًا يشمل المواد مع الهدر وأيام العمل وتكاليف المعدات وهامش الربح. ثم تُجمع هذه الحسابات الداخلية في سعر واحد يُدرج في BOQ."] },
        { id: "limitations", heading: "الحدود ومواطن التداخل", paragraphs: ["تختلف المصطلحات عمليًا حسب المنطقة. ويشير بعض المقاولين إلى BOQ المسعّر لديهم باعتباره التقدير. لكن استخدام BOQ باعتباره أداة التقدير الوحيدة، من دون إعداد تفصيل صحيح للتكاليف، يمثل مخاطرة تجارية كبيرة.", "يجب تتبع الافتراضات والاستثناءات بوضوح عند انتقال البيانات من التقدير الداخلي إلى BOQ الخارجي المقدم."] },
        { id: "quantara-workflow", heading: "كيف تدعم Quantara سير عمل التقدير", paragraphs: ["تلتقط Quantara معلومات BOQ المدعومة من ملفات PDF النصية وجداول البيانات ضمن سير عمل للمراجعة. وتعتمد التغطية وجهد التصحيح ووقت المراجعة على المصدر.", "يمكن تنظيم المعلومات المؤكدة في سجلات BOQ وتصديرها لمزيد من أعمال التقدير. وتظل دقة التقدير معتمدة على الكميات والأسعار والافتراضات المهنية."] }
