        { id: "quantara-workflow", heading: "كيف ترتبط Quantara بسير العمل", paragraphs: ["بينما يُعد الاستشاريون BOQ الأولي، قد يتلقاه المقاولون بصيغ مثل PDF. ويمكن لـ Quantara التقاط معلومات المصدر المدعومة للمراجعة وتنظيم BOQ.", "تركز Quantara حاليًا على استخراج المستندات المدعومة وهيكلة BOQ وتنظيم المشاريع والقوالب والمراجعات والمخرجات المهنية. ولا يتوفر حاليًا القياس الآلي من الرسومات."] }
