      faqs: [{ question: "ما البرامج المستخدمة لإعداد BOQ؟", answer: "تُعد ملفات BOQ تقليديًا باستخدام جداول البيانات، مثل Excel، أو برامج متخصصة في التقدير وحصر الكميات." }, { question: "هل أحتاج إلى رسومات لإعداد BOQ؟", answer: "نعم، فالرسومات والنماذج والمواصفات الدقيقة ضرورية لقياس الكميات وتحديد نطاق العمل." }, { question: "من المسؤول عن دقة BOQ؟", answer: "يكون الطرف الذي يصدر BOQ مسؤولاً عن دقته عادةً، رغم أن بعض العقود تنقل هذه المخاطر إلى المقاول." }, { question: "كيف تنظّم أقسام BOQ؟", answer: "تُنظم الأقسام عادةً حسب التخصص أو تقسيم العناصر أو الموقع الفعلي للمباني." }, { question: "ماذا يحدث إذا فات بند في BOQ؟", answer: "إذا ظهر بند مطلوب في الرسومات ولم يُدرج في BOQ، تعتمد المسؤولية المالية على شروط العقد المحددة." }],
