      faqs: [{ question: "إلى ماذا يشير اختصار BOQ؟", answer: "يشير BOQ إلى Bill of Quantities، أي جدول الكميات." }, { question: "من يُعد BOQ؟", answer: "يُعد BOQ عادةً مسّاح كميات أو استشاري تكاليف أو مقدّر نيابةً عن العميل أو المقاول الرئيسي، بحسب طريقة الشراء." }, { question: "هل يكون BOQ مسعّرًا دائمًا؟", answer: "لا. يصدر العميل أو الاستشاري BOQ غير مسعّر خلال المناقصة، ثم يملأ المقاولون أسعارهم لإنشاء BOQ مسعّر." }, { question: "هل يمكن للمقاولين تغيير BOQ؟", answer: "يجب على المقاولين عمومًا تسعيره كما صدر لضمان مقارنة عادلة. وإذا اكتشفوا أخطاء أو نواقص، يثيرون استفسارًا أو يوضحون افتراضاتهم." }, { question: "هل BOQ مستند تعاقدي؟", answer: "نعم، يشكل BOQ المسعّر جزءًا من مستندات العقد الرسمية في كثير من مسارات الشراء التقليدية." }, { question: "هل يحتاج كل مشروع إلى BOQ؟", answer: "لا. فقد لا تتطلب بعض طرق الشراء، مثل التصميم والتنفيذ أو عقود المبلغ المقطوع، BOQ رسميًا صادرًا عن العميل." }],
